const listSchedules = `-- name: ListSchedules :many
SELECT id, tenant_id, schedule_no, contract_id, contract_no, customer_id, customer_name, carrier_forwarder, vessel_name, voyage_no, port_of_loading, port_of_discharge, etd, atd, eta, ata, responsible_employee_id, responsible_name, status, remark, created_by, created_by_name, created_at, updated_by, updated_by_name, updated_at, original_eta, eta_revision, route_version, delay_days, has_temporary_call, current_progress, latest_progress_at, current_route_node_id, carrier_id, loading_port_id, loading_port_code, loading_port_timezone, discharge_port_id, discharge_port_code, discharge_port_timezone, count(*) OVER () AS total
FROM shipping_schedules
WHERE tenant_id = $1
  AND (
    $2::boolean
    OR responsible_employee_id = ANY($3::bigint[])
    OR COALESCE(customer_id, 0) = ANY($4::bigint[])
  )
  AND (
    $5::text = ''
    OR schedule_no ILIKE '%' || $5::text || '%'
    OR contract_no ILIKE '%' || $5::text || '%'
    OR customer_name ILIKE '%' || $5::text || '%'
    OR vessel_name ILIKE '%' || $5::text || '%'
    OR voyage_no ILIKE '%' || $5::text || '%'
    OR responsible_name ILIKE '%' || $5::text || '%'
  )
  AND (
    $6::text = ''
    OR ($6::text = 'ACTIVE' AND status NOT IN ('COMPLETED','CANCELLED'))
    OR ($6::text = 'ARCHIVED' AND status IN ('COMPLETED','CANCELLED'))
    OR status = $6::text
  )
  AND ($7::text = '' OR port_of_loading = $7::text)
  AND ($8::text = '' OR port_of_discharge = $8::text)
  AND ($9::date IS NULL OR etd >= $9::date)
  AND ($10::date IS NULL OR etd <= $10::date)
  AND ($11::date IS NULL OR eta >= $11::date)
  AND ($12::date IS NULL OR eta <= $12::date)
ORDER BY
  CASE WHEN eta >= CURRENT_DATE THEN 0 ELSE 1 END,
  CASE WHEN eta >= CURRENT_DATE THEN eta END ASC,
  updated_at DESC,
  -- id 收口：updated_at 会打平（同一批导入、同一次批量改），而 OFFSET 分页
  -- 遇到打平的行，翻页时同一条可能出现两次或者漏掉。
  id DESC
LIMIT $14 OFFSET $13
`

